INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(19847532, 'Infernal Flame Emperor', '狱火帝皇', 'ヘルフレイムエンペラー', 'Effect Monster', 'Pyro', 'FIRE', 9, 2700, 1600, '这张卡不能特殊召唤。 ①：这张卡上级召唤时，从自己墓地把最多5只炎属性怪兽除外才能发动。把除外数量的场上的魔法·陷阱卡破坏。'),
(58712976, 'Infernal Flame Vixen', '狱火幽灵', 'ヘルフレイムゴースト', 'XYZ Monster', 'Pyro', 'FIRE', 4, 2200, 2000, '炎族4星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力直到对方的结束阶段时上升500。此外，攻击力2500以上的这张卡被破坏时，选择双方墓地的怪兽合计3只从游戏中除外。'),
(23309606, 'Infernal Incinerator', '炎狱魔人 地狱焚魔', '炎獄魔人ヘル・バーナー', 'Effect Monster', 'Fiend', 'FIRE', 6, 2800, 1800, '不把除这张卡外的自己手卡全部丢弃去墓地，并用自己场上1只攻击力2000以上的怪兽作为祭品不能通常召唤。对方场上每存在1只怪兽，这张卡的攻击力上升200。自己场上这张卡以外的怪兽每存在1只，这张卡的攻击力下降500。'),
(28653611, 'Infernal Punisher', '地狱处刑者', 'ヘル・パニッシャー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●从卡组把1只恐龙族·水属性怪兽加入手卡。对方场上有怪兽存在的场合，可以再把加入手卡的那只怪兽特殊召唤。 ●把自己场上1只怪兽解放才能发动。从自己的手卡·卡组·墓地把1只6星以上的炎属性怪兽特殊召唤。这个效果把恶魔族以外的怪兽特殊召唤的场合，那只怪兽的效果无效化。'),
(66122213, 'Infernal Strike Fighter', '地狱俯冲轰炸机', 'ヘル・ダイブ・ボンバー', 'Synchro Monster', 'Machine', 'DARK', 7, 2600, 1800, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段2才能发动。场上的表侧表示怪兽全部破坏，给与对方破坏的怪兽的原本等级合计×200伤害。 ②：这张卡被战斗·效果破坏的场合，以自己墓地1只5星以下的机械族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(8581705, 'Infernalqueen Archfiend', '业火王后恶魔', 'インフェルノクインデーモン', 'Effect Monster', 'Fiend', 'FIRE', 4, 900, 1500, '这张卡的控制者在自己的每1个准备阶段支付500基本分。当这张卡成为对方所控制的卡的效果对象时，在效果处理时掷1次骰子，若掷出2或5，则使此效果无效并将其破坏。只要这张卡在场上存在，在每1个回合的准备阶段指定自己场上1只名称中含有「恶魔」字样的怪兽，被指定的怪兽到结束阶段为止，攻击力上升1000点。'),
(27882993, 'Infernalqueen Salmon', '狱火皇后鲑', 'インフェルノクインサーモン', 'Effect Monster', 'Fish', 'WATER', 5, 2400, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从自己的手卡·卡组·墓地选1只鱼族通常怪兽特殊召唤。 ②：这张卡被战斗或者对方的效果破坏的场合才能发动。在自己场上把「地狱兵卒鲑衍生物」（鱼族·水·1星·攻/守0）任意数量特殊召唤。'),
(18724123, 'Infernity Archer', '永火弓手', 'インフェルニティ・アーチャー', 'Effect Monster', 'Fiend', 'DARK', 6, 2000, 1000, '自己手卡是0张的场合，这张卡可以直接攻击对方玩家。'),
(99177923, 'Infernity Archfiend', '无限狱恶魔', 'インフェルニティ・デーモン', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, 1200, '①：手卡是0张的场合把这张卡抽到时，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功时才能发动。从卡组把1张「永火」卡加入手卡。这个效果在自己手卡是0张的场合才能发动和处理。'),
(85475641, 'Infernity Avenger', '永火复仇者', 'インフェルニティ・リベンジャー', 'Tuner Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这张卡在墓地存在，自己手卡是0张的场合，「永火复仇者」以外的自己场上存在的怪兽被和对方怪兽的战斗破坏送去墓地时，这张卡可以从墓地特殊召唤。这个效果特殊召唤的这张卡的等级变成和对方怪兽破坏的自己怪兽相同等级。'),
(9059700, 'Infernity Barrier', '永火防护罩', 'インフェルニティ・バリア', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有名字带有「永火」的怪兽表侧攻击表示存在，自己手卡是0张的场合才能发动。对方发动的效果怪兽的效果·魔法·陷阱卡的发动无效并破坏。'),
(7264861, 'Infernity Beast', '永火兽', 'インフェルニティ・ビースト', 'Effect Monster', 'Beast', 'DARK', 3, 1600, 1200, '自己手卡是0张的场合，得到以下效果。这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。'),
(49080532, 'Infernity Beetle', '永火甲虫', 'インフェルニティ・ビートル', 'Tuner Monster', 'Insect', 'DARK', 2, 1200, NULL, '自己手卡是0张的场合，可以把这张卡解放从自己卡组把最多2只「永火甲虫」特殊召唤。'),
(51717541, 'Infernity Break', '永火雷破', 'インフェルニティ・ブレイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己手卡是0张的场合才能发动。选择自己墓地存在的1张名字带有「永火」的卡从游戏中除外，选择对方场上存在的1张卡破坏。'),
(48144778, 'Infernity Conjurer', '永火咒法师', 'インフェルニティ・コンジュラー', 'Effect Monster', 'Fiend', 'DARK', 3, 1200, 900, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己手卡是0张，对方场上的怪兽的攻击力下降800。 ②：这张卡在墓地存在，自己手卡是0张的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(98954375, 'Infernity Destroyer', '永火破坏王', 'インフェルニティ・デストロイヤー', 'Effect Monster', 'Fiend', 'DARK', 6, 2300, 1000, '自己手卡是0张的场合，这张卡战斗破坏对方怪兽送去墓地时，给与对方基本分1600分伤害。'),
(38904695, 'Infernity Doom Archfiend', '永火地狱恶魔', 'インフェルニティ・ヘル・デーモン', 'Synchro Monster', 'Fiend', 'DARK', 6, 2200, 1600, '调整＋调整以外的怪兽1只以上 ①：1回合1次，以场上1张表侧表示的卡为对象才能发动。那张卡的效果直到回合结束时无效。自己手卡是0张的场合，可以再把那张卡破坏。 ②：只要自己手卡是0张，这张卡用和对方怪兽的战斗给与对方的战斗伤害变成2倍。 ③：这张卡为同调素材的暗属性同调怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(72896720, 'Infernity Doom Dragon', '永火死亡龙', 'インフェルニティ・デス・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 2400, '暗属性调整＋调整以外的怪兽1只以上 1回合1次，自己手卡是0张的场合选择对方场上存在的1只怪兽才能发动。选择的对方怪兽破坏，给与对方基本分破坏的怪兽的攻击力一半数值的伤害。这个效果发动的回合这张卡不能攻击。'),
(25171661, 'Infernity Dwarf', '永火矮人', 'インフェルニティ・ドワーフ', 'Effect Monster', 'Warrior', 'DARK', 2, 800, 500, '自己手卡是0张的场合，只要这张卡在自己场上表侧表示存在，自己场上存在的怪兽攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(18712704, 'Infernity Force', '永火之力', 'インフェルニティ・フォース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己手卡是0张的场合，名字带有「永火」的怪兽被选择作为攻击对象时才能发动。把1只攻击怪兽破坏，选择自己墓地存在的1只名字带有「永火」的怪兽特殊召唤。'),
(17502671, 'Infernity General', '永火将军', 'インフェルニティ・ジェネラル', 'Effect Monster', 'Fiend', 'DARK', 7, 2700, 1500, '自己手卡是0张的场合，把自己墓地存在的这张卡从游戏中除外，选择自己墓地存在的2只3星以下的名字带有「永火」的怪兽才能发动。选择的怪兽从墓地特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(51566770, 'Infernity Guardian', '永火守护者', 'インフェルニティ・ガーディアン', 'Effect Monster', 'Fiend', 'DARK', 4, 1200, 1700, '自己手卡是0张的场合，场上表侧表示存在的这张卡不会被战斗以及卡的效果破坏。'),
(14550855, 'Infernity Inferno', '永火业火', 'インフェルニティ・インフェルノ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己最多2张手卡丢弃。那之后，这个效果丢弃的数量的名字带有「永火」的卡从卡组送去墓地。'),
(71341529, 'Infernity Knight', '永火骑士', 'インフェルニティ・ナイト', 'Effect Monster', 'Fiend', 'DARK', 3, 1400, 400, '场上存在的这张卡被破坏送去墓地时，可以丢弃2张手卡把这张卡从墓地特殊召唤。'),
(66957584, 'Infernity Launcher', '永火炮', 'インフェルニティガン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己主要阶段才能发动。从自己手卡选1只「永火」怪兽送去墓地。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地，以自己墓地最多2只「永火」怪兽为对象才能发动（这个效果在自己手卡是0张的场合才能发动和处理）。那些怪兽特殊召唤。'),
(86197239, 'Infernity Mirage', '永火幻象', 'インフェルニティ・ミラージュ', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这张卡不能作从墓地的特殊召唤。自己手卡是0张的场合，把这张卡解放，选择自己墓地存在的2只名字带有「永火」的怪兽才能发动。选择的怪兽在自己场上特殊召唤。'),
(56209279, 'Infernity Necromancer', '永火死灵师', 'インフェルニティ・ネクロマンサー', 'Effect Monster', 'Fiend', 'DARK', 3, NULL, 2000, '这张卡召唤成功时，变成守备表示。此外，自己手卡是0张的场合，这张卡得到以下效果。1回合1次，可以从自己墓地选择「永火死灵师」以外的1只名字带有「永火」的怪兽特殊召唤。'),
(86547356, 'Infernity Paranoia', '永火妄想', 'インフェルニティ・パラノイア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只暗属性怪兽解放才能发动。从自己的卡组·墓地选和那只怪兽是卡名不同并是等级相同的1只「永火」怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：把墓地的这张卡除外，以自己墓地1只「永火」怪兽为对象才能发动。那只怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(54320860, 'Infernity Patriarch', '无限狱主教', 'インフェルニティ・ビショップ', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己手卡只有这1张卡的场合，这张卡可以从手卡特殊召唤。 ②：只要自己手卡是0张，自己场上的「永火」怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(82434071, 'Infernity Pawn', '永火兵卒', 'インフェルニティ・ポーン', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '①：自己手卡是0张的场合，自己抽卡阶段可以作为进行通常抽卡的代替，把墓地的这张卡除外，从以下效果选择1个发动。 ●从卡组选1张「永火」卡在卡组最上面放置。 ●从卡组选1张「炼狱」魔法·陷阱卡在自己场上盖放。'),
(53246495, 'Infernity Queen', '永火王后', 'インフェルニティ・クイーン', 'Effect Monster', 'Fiend', 'DARK', 3, 300, 900, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在，自己手卡是0张的场合，从自己墓地把1只暗属性怪兽除外，以自己场上1只暗属性怪兽为对象才能发动。这个回合，那只怪兽可以直接攻击。'),
(13582837, 'Infernity Randomizer', '永火上膛者', 'インフェルニティ・リローダー', 'Effect Monster', 'Warrior', 'DARK', 1, 900, NULL, '自己手卡是0张的场合，1回合1次，可以从自己卡组抽1张卡。这个效果抽到的卡给双方确认，怪兽卡的场合，给与对方基本分那只怪兽的等级×200的数值的伤害。魔法·陷阱卡的场合，自己受到500分伤害。'),
(15313433, 'Infernity Reflector', '永火反射面', 'インフェルニティ・リフレクター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「永火」的怪兽被战斗破坏送去墓地时，把手卡全部丢弃才能发动。那1只怪兽从自己墓地特殊召唤，给与对方基本分1000分伤害。'),
(46435376, 'Infernity Sage', '永火贤者', 'インフェルニティ・セイジ', 'Tuner Monster', 'Fiend', 'DARK', 2, 400, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己手卡全部丢弃。 ②：这张卡被送去墓地的场合才能发动。从卡组把1只「永火」怪兽送去墓地。这个效果在自己手卡是0张的场合才能发动和处理。'),
(12541409, 'Infernity Suppression', '永火压制', 'インフェルニティ・サプレッション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。自己手卡是0张的场合，这张卡在盖放的回合也能发动。 ①：自己场上有「永火」怪兽存在，对方把怪兽的效果发动时才能发动。那个效果无效。那之后，可以给与对方那只怪兽的等级×100伤害。'),
(74148483, 'Infernity Wildcat', '永火野猫', 'インフェルニティ・ワイルドキャット', 'Tuner Monster', 'Fiend', 'DARK', 3, 1400, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把手卡1只其他的「永火」怪兽送去墓地，从手卡特殊召唤。 ②：自己手卡是0张的场合，把自己墓地1只「永火」怪兽除外才能发动。这张卡的等级直到回合结束时上升或者下降1星。'),
(74823665, 'Inferno', '狱火', 'インフェルノ', 'Effect Monster', 'Pyro', 'FIRE', 4, 1100, 1900, '这张卡不能通常召唤。从自己墓地把1只炎属性怪兽除外的场合可以特殊召唤。 ①：这张卡战斗破坏对方怪兽送去墓地的场合发动。给与对方1500伤害。'),
(52684508, 'Inferno Fire Blast', '黑炎弹', '黒炎弾', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，「真红眼黑龙」不能攻击。 ①：以自己的怪兽区域1只「真红眼黑龙」为对象才能发动。给与对方那只「真红眼黑龙」的原本攻击力数值的伤害。'),
(17185260, 'Inferno Hammer', '业火之锤', 'インフェルノ・ハンマー', 'Effect Monster', 'Fiend', 'DARK', 6, 2400, NULL, '①：这张卡战斗破坏对方怪兽送去墓地时，以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽变成里侧守备表示。'),
(62767644, 'Inferno of the Ashened', '灰灭的劫火', '灰滅の劫火', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1张「灰灭之都 奥布西地暮」在自己或对方的场地区域表侧表示放置。 ②：以对方场上1张表侧表示卡和自己墓地1只8星以上的炎族·暗属性怪兽为对象才能发动。作为对象的场上的卡送去墓地，作为对象的墓地的怪兽在对方场上守备表示特殊召唤。'),
(12247206, 'Inferno Reckless Summon', '地狱的暴走召唤', '地獄の暴走召喚', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：对方场上有表侧表示怪兽存在，自己场上只有攻击力1500以下的怪兽1只特殊召唤时才能发动。那只特殊召唤的怪兽的同名怪兽从自己的手卡·卡组·墓地尽可能攻击表示特殊召唤，对方选自身场上1只表侧表示怪兽，那只怪兽的同名怪兽从自身的手卡·卡组·墓地尽可能特殊召唤。'),
(14391920, 'Inferno Tempest', '地狱暴风', 'ヘル・テンペスト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己受到3000以上的战斗伤害时才能发动。双方的卡组·墓地的怪兽全部除外。'),
(56824871, 'Infernoble Knight - Renaud', '焰圣骑士－里纳尔多', '焔聖騎士－リナルド', 'Effect Monster', 'Warrior', 'FIRE', 1, 500, 500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有战士族·炎属性怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的这张卡当作调整使用。 ②：这张卡特殊召唤成功的场合，从自己墓地的卡以及除外的自己的卡之中以「焰圣骑士-里纳尔多」以外的1只战士族·炎属性怪兽或者1张装备魔法卡为对象才能发动。那张卡加入手卡。'),
(81570454, 'Infernoble Knight - Roland', '焰圣骑士－罗兰', '焔聖騎士－ローラン', 'Effect Monster', 'Warrior', 'FIRE', 1, 500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，这张卡在手卡存在的场合，以自己场上1只表侧表示怪兽为对象才能发动。这张卡当作攻击力上升500的装备魔法卡使用给那只自己怪兽装备。 ②：这张卡被送去墓地的回合的结束阶段才能发动。从卡组把「焰圣骑士-罗兰」以外的1只战士族·炎属性怪兽或1张装备魔法卡加入手卡。'),
(95953557, 'Infernoble Knight Astolfo', '焰圣骑士－阿斯托尔福', '焔聖騎士－アストルフォ', 'Effect Monster', 'Warrior', 'FIRE', 1, 500, 200, '这个卡名的①②的效果在决斗中各能使用1次。 ①：从自己的手卡·墓地把1只战士族·炎属性怪兽除外才能发动。这张卡从手卡特殊召唤。那之后，可以把这张卡的等级变成和除外的怪兽相同。 ②：把墓地的这张卡除外才能发动。发动后第2次的自己准备阶段，除外的这张卡特殊召唤。那之后，可以从自己墓地的怪兽以及除外的自己怪兽之中选1只战士族·炎属性怪兽特殊召唤。'),
(65398390, 'Infernoble Knight Captain Oliver', '焰圣骑士将－奥利弗', '焔聖騎士将－オリヴィエ', 'Synchro Monster', 'Warrior', 'FIRE', 5, 2000, 500, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：有装备卡装备的这张卡的攻击宣言时，以场上1张表侧表示的卡为对象才能发动。那张卡破坏。 ②：以自己场上1只战士族怪兽为对象才能发动。这张卡当作调整使用从墓地特殊召唤，作为对象的自己怪兽当作攻击力上升500的装备卡使用给这张卡装备。这个效果在这张卡送去墓地的回合不能发动。'),
(40251688, 'Infernoble Knight Captain Roland', '焰圣骑士导－罗兰', '焔聖騎士導－ローラン', 'Synchro Tuner Monster', 'Warrior', 'FIRE', 5, 2000, 500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤成功的场合才能发动。这个回合的结束阶段，从卡组把1张装备魔法卡送去墓地。那之后，从卡组把1只战士族怪兽加入手卡。 ②：这张卡在墓地存在的场合，自己·对方的主要阶段，以自己场上1只战士族怪兽为对象才能发动。这张卡当作攻击力上升500的装备卡使用给那只自己怪兽装备。'),
(77656797, 'Infernoble Knight Emperor Charles', '焰圣骑士帝－查理', '焔聖騎士帝－シャルル', 'Synchro Monster', 'Warrior', 'FIRE', 9, 3000, 200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：场上的怪兽有装备卡被装备的场合才能发动（伤害步骤也能发动）。场上1张卡破坏。 ②：自己·对方的结束阶段才能发动。这张卡把1张可以装备的装备魔法卡从自己的手卡·墓地装备。那之后，可以从卡组把1只战士族·炎属性怪兽当作攻击力上升500的装备魔法卡使用给这张卡装备。'),
(94730900, 'Infernoble Knight Maugis', '焰圣骑士－莫吉斯', '焔聖騎士－モージ', 'Effect Monster', 'Warrior', 'FIRE', 4, 1500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡被送去墓地的场合，从自己墓地的卡以及除外的自己的卡之中让这张卡以外的战士族·炎属性怪兽或者「圣剑」卡合计3张回到卡组才能发动。自己从卡组抽1张。 ②：这张卡在墓地存在的场合，以自己场上1只战士族怪兽为对象才能发动。这张卡当作装备卡使用给那只自己怪兽装备。 ③：这张卡的装备怪兽不会被战斗破坏。'),
(21351206, 'Infernoble Knight Ogier', '焰圣骑士－奥吉尔', '焔聖騎士－オジエ', 'Effect Monster', 'Warrior', 'FIRE', 4, 1500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「焰圣骑士-奥吉尔」以外的1只战士族·炎属性怪兽或者1张「圣剑」卡送去墓地。 ②：这张卡在墓地存在的场合，以自己场上1只战士族怪兽为对象才能发动。这张卡当作装备卡使用给那只自己怪兽装备。 ③：这张卡的装备怪兽不会被效果破坏。'),
(58346901, 'Infernoble Knight Oliver', '焰圣骑士－奥利弗', '焔聖騎士－オリヴィエ', 'Tuner Monster', 'Warrior', 'FIRE', 4, 1000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡以及自己场上的表侧表示的卡之中把1只战士族·炎属性怪兽或者1张装备魔法卡送去墓地才能发动。这张卡从手卡作为1星怪兽特殊召唤。 ②：这张卡在墓地存在的场合，以自己场上1只战士族怪兽为对象才能发动。这张卡当作装备卡使用给那只自己怪兽装备。 ③：这张卡的装备怪兽不会成为对方的效果的对象。'),
(53404966, 'Infernoble Knight Ricciardetto', '焰圣骑士－里查德特', '焔聖騎士－リッチャルデット', 'Tuner Monster', 'Warrior', 'FIRE', 1, 500, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把手卡·墓地的这张卡除外才能发动。从手卡把1只4星以下的战士族·炎属性怪兽当作调整使用特殊召唤。 ②：这张卡召唤·特殊召唤的场合，以除「焰圣骑士-里恰尔代托」外的自己墓地1只4星以下的战士族·炎属性怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是战士族怪兽不能特殊召唤。'),
(89809665, 'Infernoble Knight Turpin', '焰圣骑士－托宾', '焔聖騎士－テュルパン', 'Effect Monster', 'Warrior', 'FIRE', 4, 1400, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有把装备卡装备的怪兽存在的场合才能发动。这张卡从手卡·墓地特殊召唤。这个效果从墓地特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡在墓地存在的场合，以自己场上1只战士族怪兽为对象才能发动。这张卡当作装备魔法卡使用给那只自己怪兽装备。 ③：把装备怪兽作为同调素材的场合，可以当作调整使用。'),
(26034577, 'Infernoid Antra', '狱炎机・别西布鲁', 'インフェルノイド・ベルゼブル', 'Effect Monster', 'Fiend', 'FIRE', 2, NULL, 2000, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地1只「狱火机」怪兽除外的场合才能从手卡特殊召唤。 ①：1回合1次，以对方场上1张表侧表示卡为对象才能发动。那张卡回到手卡。 ②：对方回合1次，把自己场上1只怪兽解放，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(88301393, 'Infernoid Attondel', '狱炎机・阿德拉梅莱克', 'インフェルノイド・アドラメレク', 'Effect Monster', 'Fiend', 'FIRE', 8, 2800, NULL, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地2只「狱火机」怪兽除外的场合才能从手卡·墓地特殊召唤。 ①：这张卡战斗破坏对方怪兽送去墓地时才能发动。这张卡只再1次可以继续攻击。 ②：自己·对方回合1次，把自己场上1只怪兽解放，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(58446973, 'Infernoid Decatron', '狱炎机・十进管', 'インフェルノイド・デカトロン', 'Tuner Monster', 'Fiend', 'FIRE', 1, 500, 200, '①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「狱火机十进管」以外的1只「狱火机」怪兽送去墓地。这张卡等级上升那只怪兽的等级数值，得到和那只怪兽的原本的卡名·效果相同的卡名·效果。'),
(23440231, 'Infernoid Devyaty', '狱炎机・莉莉丝', 'インフェルノイド・リリス', 'Effect Monster', 'Fiend', 'FIRE', 9, 2900, 2900, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地3只「狱火机」怪兽除外的场合才能从手卡·墓地特殊召唤。 ①：这张卡特殊召唤时才能发动。「炼狱」卡以外的场上的魔法·陷阱卡全部破坏。 ②：1回合1次，这张卡以外的怪兽的效果发动时，把自己场上1只怪兽解放才能发动。那个发动无效并除外。'),
(97051536, 'Infernoid Evil', '狱炎机・邪恶', 'インフェルノイド・イヴィル', 'Fusion Monster', 'Fiend', 'FIRE', 1, 1100, 1100, '「狱火机」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合，从自己墓地把1只「狱火机」怪兽除外才能发动。和那只怪兽的等级相同数量的「狱火机」怪兽从卡组送去墓地（同名卡最多1张）。 ②：这张卡被送去墓地的场合或者被除外的场合才能发动。从卡组把1张「炼狱」魔法·陷阱卡加入手卡。'),
(34446231, 'Infernoid Flood', '狱炎机・洪潦', 'インフェルノイド・フラッド', 'Link Monster', 'Fiend', 'FIRE', NULL, 3000, NULL, '包含「狱火机」怪兽的怪兽2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：对方把怪兽特殊召唤之际，把自己场上1只怪兽解放才能发动。那次特殊召唤无效，那些怪兽除外。 ②：从自己墓地有卡被除外的场合才能发动。场上1张卡除外。 ③：连接召唤的这张卡被对方破坏的场合才能发动。从卡组把1只「狱火机」怪兽无视召唤条件特殊召唤。'),
(52038272, 'Infernoid Harmadik', '狱炎机・路希弗格斯', 'インフェルノイド・ルキフグス', 'Effect Monster', 'Fiend', 'FIRE', 3, 1600, NULL, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地1只「狱火机」怪兽除外的场合才能从手卡特殊召唤。 ①：1回合1次，以场上1只怪兽为对象才能发动（这个效果发动的回合，这张卡不能攻击）。那只怪兽破坏。 ②：对方回合1次，把自己场上1只怪兽解放，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(14799437, 'Infernoid Onuncu', '狱炎机・拿赫摩斯', 'インフェルノイド・ネヘモス', 'Effect Monster', 'Fiend', 'FIRE', 10, 3000, 3000, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地3只「狱火机」怪兽除外的场合才能从手卡·墓地特殊召唤。 ①：这张卡特殊召唤时才能发动。场上的其他怪兽全部破坏。 ②：1回合1次，魔法·陷阱卡的效果发动时，把自己场上1只怪兽解放才能发动。那个发动无效并除外。'),
(89423971, 'Infernoid Patrulea', '狱炎机・阿斯塔罗斯', 'インフェルノイド・アスタロス', 'Effect Monster', 'Fiend', 'FIRE', 4, 1800, NULL, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地1只「狱火机」怪兽除外的场合才能从手卡特殊召唤。 ①：1回合1次，以场上1张魔法·陷阱卡为对象才能发动（这个效果发动的回合，这张卡不能攻击）。那张卡破坏。 ②：对方回合1次，把自己场上1只怪兽解放，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(25811989, 'Infernoid Piaty', '狱炎机・阿斯蒙达', 'インフェルノイド・アシュメダイ', 'Effect Monster', 'Fiend', 'FIRE', 5, 2200, NULL, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地2只「狱火机」怪兽除外的场合才能从手卡·墓地特殊召唤。 ①：这张卡向对方怪兽的攻击给与对方战斗伤害时才能发动。对方手卡随机1张送去墓地。 ②：自己·对方回合1次，把自己场上1只怪兽解放，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(60551528, 'Infernoid Pirmais', '狱炎机・撒坦', 'インフェルノイド・シャイターン', 'Effect Monster', 'Fiend', 'FIRE', 1, NULL, NULL, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地1只「狱火机」怪兽除外的场合才能从手卡特殊召唤。 ①：1回合1次，以场上1张里侧表示卡为对象才能发动（不能对应这个效果的发动把作为对象的魔法·陷阱卡发动）。那张卡回到卡组。 ②：对方回合1次，把自己场上1只怪兽解放，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(51316684, 'Infernoid Seitsemas', '狱炎机・巴耶尔', 'インフェルノイド・ヴァエル', 'Effect Monster', 'Fiend', 'FIRE', 7, 2600, NULL, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地2只「狱火机」怪兽除外的场合才能从手卡·墓地特殊召唤。 ①：这张卡向对方怪兽攻击的战斗阶段结束时才能发动。场上1张卡除外。 ②：自己·对方回合1次，把自己场上1只怪兽解放，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(96055137, 'Infernoid Sjette', '狱炎机・贝尔芬葛', 'インフェルノイド・ベルフェゴル', 'Effect Monster', 'Fiend', 'FIRE', 6, 2400, NULL, '这张卡不能通常召唤。自己场上的效果怪兽的等级·阶级的合计是8以下时，把自己的手卡·墓地2只「狱火机」怪兽除外的场合才能从手卡·墓地特殊召唤。 ①：这张卡的攻击宣言时才能发动。对方从自身的额外卡组把1只怪兽除外。 ②：自己·对方回合1次，把自己场上1只怪兽解放，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(82734805, 'Infernoid Tierra', '狱炎机・缇耶拉', 'インフェルノイド・ティエラ', 'Fusion Monster', 'Fiend', 'FIRE', 11, 3400, 3600, '「狱火机·拿玛」＋「狱火机·莉莉丝」＋「狱火机」怪兽1只以上 ①：这张卡融合召唤时才能发动。那些作为融合素材的怪兽种类的以下效果适用。 ●3种类以上：双方各自从自身的额外卡组把3张卡送去墓地。 ●5种类以上：双方各自从自身卡组上面把3张卡送去墓地。 ●8种类以上：双方各自让自身的除外状态的最多3张卡回到墓地。 ●10种类以上：有手卡的玩家把那些手卡全部送去墓地。'),
(34822851, 'Infernoid Token', '炼狱的泛滥', '煉獄の氾爛', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(35419032, 'Infestation Infection', '侵略的侵食感染', '侵略の侵喰感染', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，让自己手卡或者自己场上表侧表示存在的1只名字带有「入魔」的怪兽回到卡组才能发动。从自己卡组把1只名字带有「入魔」的怪兽加入手卡。'),
(27541267, 'Infestation Pandemic', '侵略的泛发感染', '侵略の汎発感染', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上的全部「入魔」怪兽直到回合结束时不受这张卡以外的魔法·陷阱卡的效果影响。'),
(81218874, 'Infestation Ripples', '侵略的波纹', '侵略の波紋', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '支付500基本分，选择自己墓地存在的1只4星以下的名字带有「侵入魔鬼」的怪兽发动。选择的怪兽从墓地特殊召唤。'),
(90934570, 'Infestation Terminus', '侵略的侵食崩坏', '侵略の侵喰崩壊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「入魔」的怪兽从游戏中除外，选择对方场上2张卡回到持有者手卡。'),
(27207573, 'Infestation Tool', '侵略的手段', '侵略の手段', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从自己卡组把1只名字带有「侵入魔鬼」的怪兽送去墓地，选择自己场上表侧表示存在的1只名字带有「侵入魔鬼」的怪兽发动。选择的怪兽的攻击力直到结束阶段时上升800。'),
(18816758, 'Infestation Wave', '侵略的波动', '侵略の波動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '让自己场上表侧表示存在的1只上级召唤成功的名字带有「侵入魔鬼」的怪兽回到手卡发动。选择对方场上存在的1张卡破坏。'),
(39078434, 'Infinite Antlion', '巨蚁地狱救世主', 'ジャイアント・メサイア', 'Effect Monster', 'Insect', 'EARTH', 3, 1200, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从自己的手卡·墓地选1只昆虫族怪兽当作攻击力·守备力上升500的装备卡使用给这张卡装备。 ③：1回合1次，昆虫族怪兽进行战斗的伤害步骤开始时，以自己以及对方场上的卡各1张为对象才能发动。那些卡破坏。'),
(94163677, 'Infinite Cards', '无限的手札', '無限の手札', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上表侧表示存在，双方没有手卡数量限制。'),
(54109233, 'Infinite Dismissal', '救世主之蚁地狱', 'メサイアの蟻地獄', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '3星以下的怪兽召唤·反转召唤的回合的结束阶段破坏。'),
(10045474, 'Infinite Impermanence', '无限泡影', '無限泡影', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上没有卡存在的场合，这张卡的发动从手卡也能用。 ①：以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。盖放的这张卡发动的场合，再在这个回合中让和这张卡相同纵列的其他的魔法·陷阱卡的效果无效化。'),
(72883039, 'Infinite Light', '无限光', '無限光アイン・ソフ・オウル', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '把自己的魔法与陷阱区域1张表侧表示的「无限械」送去墓地才能把这张卡发动。 ①：这张卡不会被对方的效果破坏。 ②：自己场上的「时械神」怪兽不会成为效果的对象，双方不能让场上的「时械神」怪兽回到卡组。 ③：1回合1次，自己场上没有怪兽存在的场合才能发动。从自己的手卡·卡组·墓地各把最多1只卡名不同的「时械神」怪兽无视召唤条件特殊召唤。'),
(36894320, 'Infinite Machine', '无限械', '無限械アイン・ソフ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '把自己的魔法与陷阱区域1张表侧表示的「虚无械」送去墓地才能把这张卡发动。 ①：这张卡1回合只有1次不会被对方的效果破坏。 ②：1回合1次，可以从以下效果选择1个发动。 ●自己·对方的主要阶段才能发动。从手卡把1只「时械神」怪兽特殊召唤。 ●以自己墓地1只「时械神」怪兽为对象才能发动。那只怪兽回到卡组。那之后，可以从手卡·卡组选1张「无限光」在自己的魔法与陷阱区域盖放。'),
(62034800, 'Infinitrack Anchor Drill', '无限起动 岩锚钻孔机', '無限起動ロックアンカー', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从手卡把「无限起动 攀岩锚挖掘机」以外的1只机械族·地属性怪兽守备表示特殊召唤。 ②：以这张卡以外的自己场上1只机械族怪兽为对象才能发动。那只怪兽和这张卡直到回合结束时变成那2只的原本等级合计的等级。'),
(76830505, 'Infinitrack Brutal Dozer', '无限起动 暴虐推土机', '無限起動ブルータルドーザー', 'Effect Monster', 'Machine', 'EARTH', 5, 1900, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只机械族·地属性怪兽解放才能发动。这张卡从手卡守备表示特殊召唤。 ②：这张卡从手卡的特殊召唤成功的场合才能发动。从卡组把「无限起动 残暴推土机」以外的1只「无限起动」怪兽效果无效守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族·地属性怪兽不能特殊召唤。'),
(98439949, 'Infinitrack Crab Crane', '无限起动 蟹式起重机', '無限起動キャンサークレーン', 'Effect Monster', 'Machine', 'EARTH', 5, 2100, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只机械族·地属性怪兽解放才能发动。这张卡从手卡守备表示特殊召唤。 ②：从自己墓地把1只机械族怪兽除外才能发动。从卡组把1张「超接地展开」加入手卡。'),
(34923554, 'Infinitrack Drag Shovel', '无限起动 龙式挖掘机', '無限起動ドラグショベル', 'Effect Monster', 'Machine', 'EARTH', 5, 1500, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只机械族·地属性怪兽解放才能发动。这张卡从手卡守备表示特殊召唤。 ②：从自己墓地把1只机械族怪兽除外才能发动。从卡组把1张「超信地旋回」加入手卡。'),
(97584719, 'Infinitrack Earth Slicer', '无限起动 大地撼动者', '無限起動アースシェイカー', 'XYZ Monster', 'Machine', 'EARTH', 9, 3100, 2100, '9星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡的超量素材任意数量取除，以那个数量的场上的卡为对象才能发动。那些卡破坏。 ②：这张卡战斗破坏对方怪兽时才能发动。那只怪兽在这张卡下面重叠作为超量素材。 ③：这张卡在墓地存在的场合，把自己场上1只机械族连接怪兽解放才能发动。这张卡守备表示特殊召唤。'),
(69073023, 'Infinitrack Fortress Megaclops', '无限起动要塞 百万吨盖尔', '無限起動要塞メガトンゲイル', 'Link Monster', 'Machine', 'EARTH', NULL, 4000, NULL, '超量怪兽3只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡只要在怪兽区域存在，不受这张卡以及超量怪兽以外的怪兽的效果影响，不会被和超量怪兽以外的怪兽的战斗破坏。 ②：以自己墓地1只超量怪兽和对方场上1张卡为对象才能发动。那只墓地的超量怪兽特殊召唤，那张对方的卡在下面重叠作为超量素材。这个效果的发动后，直到回合结束时对方受到的全部伤害变成一半。'),
(23689428, 'Infinitrack Goliath', '无限起动 歌利亚', '無限起動ゴライアス', 'Link Monster', 'Machine', 'EARTH', NULL, 1000, NULL, '连接怪兽以外的「无限起动」怪兽1只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡从场上送去墓地的场合，以自己场上1只超量怪兽为对象才能发动。把这张卡在那只怪兽下面重叠作为超量素材。 ②：持有这张卡作为素材中的原本种族是机械族的超量怪兽得到以下效果。 ●这张卡不会被效果破坏。'),
(35645105, 'Infinitrack Harvester', '无限起动 收割机', '無限起動ハーヴェスター', 'Effect Monster', 'Machine', 'EARTH', 2, NULL, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「无限起动 收割机」以外的1只「无限起动」怪兽加入手卡。 ②：以这张卡以外的自己场上1只机械族怪兽为对象才能发动。那只怪兽和这张卡直到回合结束时变成那2只的原本等级合计的等级。'),
(60195675, 'Infinitrack Mountain Smasher', '无限起动 破土碎山', '無限起動コロッサルマウンテン', 'XYZ Monster', 'Machine', 'EARTH', 7, 2100, 3100, '7星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。这张卡的攻击力上升1000。 ②：这张卡战斗破坏对方怪兽时才能发动。那只怪兽在这张卡下面重叠作为超量素材。 ③：这张卡在墓地存在的场合，把自己场上1只机械族连接怪兽解放才能发动。这张卡守备表示特殊召唤。'),
(24701066, 'Infinitrack River Stormer', '无限起动 大河风暴', '無限起動リヴァーストーム', 'XYZ Monster', 'Machine', 'EARTH', 5, 2500, 500, '5星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组选1只机械族·地属性怪兽加入手卡或送去墓地。 ②：这张卡战斗破坏对方怪兽时才能发动。那只怪兽作为这张卡的超量素材。 ③：这张卡在墓地存在的场合，把自己场上1只机械族连接怪兽解放才能发动。这张卡守备表示特殊召唤。'),
(5205146, 'Infinitrack Road Roller', '无限起动 压路机', '無限起動ロードローラー', 'Effect Monster', 'Machine', 'EARTH', 5, 2100, 2100, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，机械族·地属性怪兽被解放的场合或者被表侧表示除外的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：持有这张卡作为素材中的原本种族是机械族的超量怪兽得到以下效果。 ●只要这张卡在怪兽区域存在，对方场上的表侧表示怪兽变成守备表示，守备力下降1000。'),
(61912252, 'Infinitrack Trencher', '无限起动 链锯挖沟机', '無限起動トレンチャー', 'Effect Monster', 'Machine', 'EARTH', 5, 500, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只机械族·地属性怪兽解放才能发动。这张卡从手卡守备表示特殊召唤。 ②：把墓地的这张卡除外，以「无限起动 挖沟机」以外的自己墓地1只5星以下的「无限起动」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(97316367, 'Infinitrack Tunneller', '无限起动 削岩掘进机', '無限起動スクレイパー', 'Effect Monster', 'Machine', 'EARTH', 5, 2200, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只机械族·地属性怪兽解放才能发动。这张卡从手卡守备表示特殊召唤。 ②：把墓地的这张卡除外，以自己墓地5只机械族·地属性怪兽为对象才能发动。那些怪兽回到卡组洗切。那之后，自己从卡组抽2张。'),
(76520646, 'Infinity Dark', '无限暗魔', 'インフィニティ・ダーク', 'Gemini Monster', 'Fiend', 'DARK', 4, 1500, 1200, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡的攻击宣言时，可以把对方场上存在的1只表侧表示怪兽的表示形式改变。'),
(54936498, 'Influence Dragon', '影响龙', 'インフルーエンス・ドラゴン', 'Tuner Monster', 'Dragon', 'WIND', 3, 300, 900, '1回合1次，选择自己场上表侧表示存在的1只怪兽才能发动。选择的怪兽直到结束阶段时变成龙族。'),
(4941482, 'Informer Spider', '密探蜘蛛', 'インフォーマー・スパイダー', 'Effect Monster', 'Insect', 'EARTH', 4, 500, 1800, '场上存在的这张卡被卡的效果送去墓地时，得到对方场上守备表示存在的1只怪兽的控制权。'),
(20057949, 'Inherited Fortune', '命运继承', 'フォーチュン・インハーリット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「命运女郎」的怪兽被破坏的回合才能发动。下次的自己的准备阶段时可以从手卡把名字带有「命运女郎」的怪兽最多2只特殊召唤。'),
(79575620, 'Injection Fairy Lily', '注射天使 莉莉', 'お注射天使リリー', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 400, 1500, '①：这张卡进行战斗的伤害计算时1次，支付2000基本分才能发动。这张卡的攻击力只在那次伤害计算时上升3000。'),
(39703254, 'Inmato', '番茄小子', 'トマボー', 'Effect Monster', 'Plant', 'DARK', 3, 1400, 800, '场上表侧表示存在的这张卡以外的1只植物族怪兽成为对方的魔法·陷阱卡的效果的对象时才能发动。把自己场上存在的这张卡解放，从自己卡组抽2张卡。'),
(300205001, 'Inner Conflict', NULL, NULL, 'Skill Card', 'Yami Bakura', NULL, NULL, NULL, NULL, NULL),
(97923414, 'Inpachi', '大木人18', '大木人１８', 'Normal Monster', 'Machine', 'EARTH', 4, 1600, 1900, '其原型是被砍倒的巨树寄宿了邪恶灵魂的姿态。袭击迷失在森林里的旅人。'),
(3492538, 'Insect Armor with Laser Cannon', '附火器的机甲铠', '火器付機甲鎧', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '昆虫族怪兽才能装备。 ①：装备怪兽的攻击力上升700。'),
(23615409, 'Insect Barrier', '除虫网', '虫除けバリアー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方场上存在的全部昆虫族的怪兽不能宣言攻击。'),
(96965364, 'Insect Imitation', '孵化', '孵化', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只怪兽解放才能发动。比解放的怪兽等级高1星的1只昆虫族怪兽从卡组特殊召唤。'),
(86527709, 'Insect Invitation', '虫之专场', '虫だけエリアー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：这个回合没有召唤·反转召唤·特殊召唤的对方场上的表侧表示怪兽变成昆虫族。 ②：以自己的除外状态的3只昆虫族怪兽为对象才能发动。那些怪兽回到卡组。那之后，自己抽1张。 ③：这张卡从手卡送去墓地的回合的结束阶段才能发动。这张卡在自己场上表侧表示放置。'),
(35052053, 'Insect Knight', '甲虫装甲骑士', '甲虫装甲騎士', 'Normal Monster', 'Insect', 'EARTH', 4, 1900, 1500, '在昆虫战士之中，属于精英中的精英的「无死虫团」的精锐骑士。不能无视它们强大的战斗能力。'),
(91512836, 'Insect Monster Token', '昆虫女王', 'インセクト女王', 'Token', 'Insect', NULL, NULL, NULL, NULL, NULL),
(22991179, 'Insect Neglect', '无视加护', '無視加護', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时，可以把自己墓地存在的1只昆虫族怪兽从游戏中除外，那次攻击无效。'),
(37957847, 'Insect Princess', '昆虫公主', 'インセクト・プリンセス', 'Effect Monster', 'Insect', 'WIND', 6, 1900, 1200, '只要这张卡在场上表侧表示存在，对方场上所有以表侧表示存在的昆虫族怪兽全部变成攻击表示。这张卡每战斗破坏1只昆虫族怪兽，攻击力上升500点。'),
(91512835, 'Insect Queen', '昆虫女王', 'インセクト女王', 'Effect Monster', 'Insect', 'EARTH', 7, 2200, 2400, '①：这张卡的攻击力上升场上的昆虫族怪兽数量×200。 ②：这张卡的攻击宣言之际，自己必须把自己场上1只其他怪兽解放。 ③：这张卡战斗破坏对方怪兽的回合的结束阶段发动。在自己场上把1只「昆虫怪兽衍生物」（昆虫族·地·1星·攻/守100）攻击表示特殊召唤。'),
(7019529, 'Insect Soldiers of the Sky', '空中的昆虫兵', '空の昆虫兵', 'Effect Monster', 'Insect', 'WIND', 3, 1000, 800, '攻击风属性的怪兽时，伤害阶段时攻击力上升1000。'),
(16227556, 'Inspection', '检阅', '検閲', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次对方的准备阶段可以支付500基本分，随机看对方1张手卡。'),
(15397015, 'Inspector Boarder', '冲浪检察官', 'インスペクト・ボーダー', 'Effect Monster', 'Machine', 'LIGHT', 4, 2000, 2000, '自己场上有怪兽存在的场合，这张卡不能召唤·特殊召唤。 ①：只要这张卡在怪兽区域存在，那个期间双方各自在1回合可以发动的怪兽的效果次数变成最多到场上的怪兽的种类（仪式·融合·同调·超量·灵摆·连接）数量次数为止。'),
(25005816, 'Inspiration', '鼓舞', '鼓舞', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升700。'),
(16169772, 'Instant Contact', '简易接触', 'インスタント・コンタクト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：支付1000基本分才能发动。7星以下的1只「元素英雄」怪兽或者「新空间侠」怪兽无视召唤条件从额外卡组特殊召唤。自己的场上以及墓地没有「元素英雄 新宇侠」存在的场合，这个效果特殊召唤的怪兽不能攻击，效果无效化，结束阶段回到持有者的额外卡组。'),
(1845204, 'Instant Fusion', '简易结合', '簡易融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：支付1000基本分才能发动。把1只5星以下的融合怪兽当作融合召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽不能攻击，结束阶段破坏。'),
(11913700, 'Instant Neo Space', '简易新宇空间', 'インスタント・ネオスペース', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「元素英雄 新宇侠」作为融合素材的融合怪兽才能装备。这张卡装备的融合怪兽在结束阶段时可以不发动回到卡组效果。装备怪兽从场上离开的场合，可以从自己的手卡·卡组·墓地把1只「元素英雄 新宇侠」特殊召唤。'),
(59695933, 'Intercept', '截获', 'インターセプト', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '需要1只怪兽解放的怪兽的召唤成功时才能发动。得到那1只怪兽的控制权。'),
(39440937, 'Intercept Wave', '妨害电波', '妨害電波', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '双方场上存在的同调怪兽全部变成守备表示，结束阶段时场上表侧表示存在的同调怪兽全部回到额外卡组。'),
(19113101, 'Interceptomato', '阻碍番茄', 'プリベントマト', 'Effect Monster', 'Plant', 'EARTH', 2, 800, 800, '把墓地的这张卡从游戏中除外才能发动。这个回合，自己受到的效果伤害变成0。这个效果在对方回合才能发动。'),
(60238002, 'Interdimensional Matter Forwarder', '亚空间物质回送装置', '亜空間物質回送装置', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：以场上1只怪兽为对象才能发动。那只怪兽除外。那之后，这个效果除外的怪兽回到场上。 ②：对方的效果发动的场合，以效果被无效化的1只表侧表示怪兽为对象才能发动。那只怪兽除外。那之后，这个效果除外的怪兽回到场上。 ③：场上的这张卡为对象的对方的效果适用之际，这张卡直到下个回合的结束阶段除外。'),
(36261276, 'Interdimensional Matter Transporter', '亚空间物质传送装置', '亜空間物質転送装置', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。那只自己的表侧表示怪兽直到结束阶段除外。'),
(57384901, 'Interdimensional Warp', '亚空间跳跃装置', '亜空間ジャンプ装置', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上1只怪兽和对方场上1只放置有A指示物的怪兽控制权交换。'),
(14729426, 'Interplanetary Invader "A"', '来自惑星的物体A', '惑星からの物体A', 'Effect Monster', 'Reptile', 'LIGHT', 1, NULL, 500, '向场上表侧攻击表示存在的这张卡攻击的怪兽的控制权在战斗阶段结束时得到。'),
(80208323, 'Interplanetarypurplythorny Beast', '异界的棘紫兽', '異界の棘紫獣', 'Effect Monster', 'Beast', 'DARK', 5, 1100, 2200, '这张卡在墓地存在，自己场上的怪兽被战斗破坏送去墓地时，这张卡可以从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合从游戏中除外。「异界的棘紫兽」的效果1回合只能发动1次。'),
(25206027, 'Interplanetarypurplythorny Dragon', '异界的棘紫龙', '異界の棘紫竜', 'Effect Monster', 'Dragon', 'DARK', 5, 2200, 1100, '自己场上的怪兽被战斗或者卡的效果破坏送去墓地的场合，这张卡可以从手卡特殊召唤。'),
(2414168, 'Interrupt Resistor', '中断反抗军', 'インタラプト・レジスタンス', 'Effect Monster', 'Cyberse', 'LIGHT', 6, NULL, 2100, '①：自己受到战斗伤害时才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡的攻击力上升受到的伤害的数值。 ②：1回合1次，这张卡以外的自己的守备表示怪兽被对方怪兽攻击的伤害计算时才能发动。那只自己怪兽只在那次伤害计算时变成和这张卡相同守备力，不会被那次战斗破坏。'),
(99330325, 'Interrupted Kaiju Slumber', '被打扰的坏兽安眠', '妨げられた壊獣の眠り', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：场上的怪兽全部破坏。那之后，从卡组把卡名不同的「坏兽」怪兽在自己·对方的场上各1只攻击表示特殊召唤。这个效果特殊召唤的怪兽不能把表示形式变更，可以攻击的场合必须作出攻击。 ②：把墓地的这张卡除外才能发动。从卡组把1只「坏兽」怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(91592030, 'Intimidating Ore - Summonite', '威迫矿石-迫选召唤石', '威迫鉱石－サモナイト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地3只怪兽为对象才能发动。自己从那3只之中选1只。那之后，对方从以下效果选1个，自己让那个效果适用。 ●选的怪兽特殊召唤。 ●选的怪兽以外的作为对象的怪兽尽可能特殊召唤。'),
(300205002, 'Into the Darkness Below', NULL, NULL, 'Skill Card', 'Yami Bakura', NULL, NULL, NULL, NULL, NULL),
(93946239, 'Into the Void', '无之炼狱', '無の煉獄', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己手卡是3张以上的场合才能发动。从自己卡组抽1张卡，这个回合的结束阶段时自己手卡全部丢弃。'),
(23122036, 'Intrigue Shield', '阴谋之盾', '陰謀の盾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成装备卡，给自己场上1只怪兽装备。装备怪兽只要表侧攻击表示存在，1回合只有1次不会被战斗破坏。此外，装备怪兽的战斗发生的对自己的战斗伤害变成0。'),
(69091732, 'Introduction to Gallantry', '义贼的入门书', '義賊の入門書', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方手卡有5张以上时才能发动。对方随机丢弃1张手卡。'),
(59277750, 'Intruder Alarm - Yellow Alert', '敌袭警报', '敵襲警報－イエローアラート－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方怪兽的攻击宣言时才能发动。从手卡把1只怪兽特殊召唤。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，对方不能选择其他怪兽作为攻击对象。这个效果特殊召唤的怪兽在战斗阶段结束时回到持有者手卡。'),
(28450915, 'Invader from Another Dimension', '来自异次元的侵略者', '異次元からの侵略者', 'Normal Monster', 'Fiend', 'DARK', 4, 950, 1400, '从银河系以外来到地球的外星人。'),
(56647086, 'Invader of Darkness', '暗黑之侵略者', '暗黒の侵略者', 'Effect Monster', 'Fiend', 'DARK', 8, 2900, 2500, '只要这张卡在自己场上以表侧表示存在，对方不能发动速攻魔法卡。'),
(3056267, 'Invader of the Throne', '王座侵略者', '王座の侵略者', 'Flip Effect Monster', 'Warrior', 'EARTH', 4, 1350, 1700, '反转：选择对方场上存在的1只怪兽，那只怪兽和这张卡的控制权交换。这个效果在战斗阶段不能发动。'),
(26082229, 'Invasion of Flames', '侵略之炎', '侵略の炎', 'Effect Monster', 'Pyro', 'FIRE', 3, 1300, 1200, '这张卡召唤成功时，陷阱卡不能发动。'),
(79161790, 'Inverse Universe', '反转世界', '反転世界', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的全部效果怪兽的攻击力·守备力交换。'),
(98374133, 'Invigoration', '觉醒', '覚醒', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '地属性的怪兽才能装备。装备的怪兽攻击力上升400，守备力下降200。'),
(17722185, 'Invincibility Barrier', '无敌光环', 'インヴィンシブル・ヘイロー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，把自己场上1只表侧表示的仪式·融合·同调·超量·灵摆·连接怪兽除外才能发动。这个回合，这张卡在魔法与陷阱区域存在期间，和除外的怪兽相同种类（仪式·融合·同调·超量·灵摆·连接）的怪兽的效果无效化。'),
(52675689, 'Invitation to a Dark Sleep', '诱发暗黑长眠的路西法', '暗黒の眠りを誘うルシファー', 'Effect Monster', 'Spellcaster', 'DARK', 5, 1500, 1800, '①：这张卡召唤·反转召唤成功的场合，以对方场上1只怪兽为对象发动。这张卡得到以下效果。 ●只要这张卡在怪兽区域存在，作为对象的怪兽不能攻击。'),
(74063034, 'Invocation', '召唤魔术', '召喚魔術', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：手卡的怪兽作为融合素材，把1只融合怪兽融合召唤。「召唤兽」融合怪兽融合召唤的场合，也能把自己场上以及自己·对方的墓地的怪兽除外作为融合素材。 ②：这张卡在墓地存在的场合，以自己的除外状态的1只「召唤师 阿莱斯特」为对象才能发动。这张卡回到卡组，作为对象的怪兽加入手卡。'),
(97300502, 'Invoked Augoeides', '召唤兽 奥格艾迪斯', '召喚獣アウゴエイデス', 'Fusion Monster', 'Fairy', 'LIGHT', 8, 2000, 2800, '「召唤师 阿莱斯特」＋融合怪兽 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合或者对方场上有怪兽特殊召唤的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。 ②：1回合1次，从自己墓地把1只融合怪兽除外才能发动。这张卡的攻击力直到对方回合结束时上升除外的怪兽的攻击力数值。'),
(13529466, 'Invoked Caliga', '召唤兽 卡里古拉', '召喚獣カリギュラ', 'Fusion Monster', 'Beast', 'DARK', 4, 1000, 1800, '「召唤师 阿莱斯特」＋暗属性怪兽 ①：只要这张卡在怪兽区域存在，那个期间双方在1回合只能有1次把怪兽的效果发动，在同1次的战斗阶段中只能用1只怪兽攻击。'),
(85908279, 'Invoked Cocytus', '召唤兽 科库托斯', '召喚獣コキュートス', 'Fusion Monster', 'Dragon', 'WATER', 6, 1800, 2900, '「召唤师 阿莱斯特」＋水属性怪兽 ①：场上的这张卡不会成为对方的效果的对象，不会被对方的效果破坏。 ②：这张卡可以用表侧守备表示的状态作出攻击。那个场合，攻击力数值适用进行伤害计算。'),
(11270236, 'Invoked Elysium', '召唤兽 埃律西昂', '召喚獣エリュシオン', 'Fusion Monster', 'Fairy', 'LIGHT', 10, 3200, 4000, '「召唤兽」怪兽＋从额外卡组特殊召唤的怪兽 这张卡用以上记的卡为融合素材的融合召唤才能从额外卡组特殊召唤。 ①：只要这张卡在怪兽区域存在，这张卡的属性也当作「暗」「地」「水」「炎」「风」使用。 ②：1回合1次，以自己的场上·墓地1只「召唤兽」怪兽为对象才能发动。那只怪兽以及持有和那只怪兽相同属性的对方场上的怪兽全部除外。这个效果在对方回合也能发动。'),
(48791583, 'Invoked Magellanica', '召唤兽 墨瓦腊泥加', '召喚獣メガラニカ', 'Fusion Monster', 'Rock', 'EARTH', 8, 3000, 3300, '「召唤师 阿莱斯特」＋地属性怪兽'),
(38423248, 'Invoked Magistus Omega', '召唤兽 伟魔・瑟利昂', '召喚獣マギストス・セリオン', 'Fusion Monster', 'Beast', 'DARK', 8, 2800, 2000, '「召唤师 阿莱斯特」＋融合·同调·超量·连接怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以自己墓地1只融合·同调·超量·连接怪兽和场上1只怪兽为对象才能发动。那些怪兽除外。 ②：融合召唤的这张卡被战斗·效果破坏的场合才能发动。从卡组把1只魔法师族·4星怪兽特殊召唤。那之后，可以把这张卡当作攻击力上升1000的装备魔法卡使用给那只怪兽装备。'),
(75286621, 'Invoked Mechaba', '召唤兽 梅尔卡巴', '召喚獣メルカバー', 'Fusion Monster', 'Machine', 'LIGHT', 9, 2500, 2100, '「召唤师 阿莱斯特」＋光属性怪兽 ①：1回合1次，怪兽的效果·魔法·陷阱卡发动时，把和那个效果相同种类（怪兽·魔法·陷阱）的1张卡从手卡送去墓地才能发动。那个发动无效并除外。'),
(12307878, 'Invoked Purgatrio', '召唤兽 普尔加托里奥', '召喚獣プルガトリオ', 'Fusion Monster', 'Fiend', 'FIRE', 7, 2300, 2000, '「召唤师 阿莱斯特」＋炎属性怪兽 ①：这张卡的攻击力上升对方场上的卡数量×200。 ②：这张卡可以向对方怪兽全部各作1次攻击，向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(49513164, 'Invoked Raidjin', '召唤兽 雷丁', '召喚獣ライディーン', 'Fusion Monster', 'Warrior', 'WIND', 5, 2200, 2400, '「召唤师 阿莱斯特」＋风属性怪兽 ①：1回合1次，以场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。这个效果在对方回合也能发动。'),
(95395761, 'Inzektor Ant', '甲虫装机 蚂蚁', '甲虫装機 アーマイゼ', 'Effect Monster', 'Insect', 'DARK', 3, 200, 600, '1回合1次，可以从自己的手卡·墓地把1只名字带有「甲虫装机」的怪兽当作装备卡使用给这张卡装备。这张卡当作装备卡使用而装备中的场合，装备怪兽的等级上升3星，攻击力·守备力上升这张卡的各自数值。装备怪兽被破坏的场合，可以作为代替把这张卡破坏。'),
(87973893, 'Inzektor Axe - Zektahawk', '甲虫装机的魔斧 虫装战斧', '甲虫装機の魔斧 ゼクトホーク', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「甲虫装机」的怪兽才能装备。装备怪兽的攻击力上升1000。装备怪兽的攻击宣言时，对方不能把魔法·陷阱卡发动。'),
(21790410, 'Inzektor Centipede', '甲虫装机 蜈蚣', '甲虫装機 センチピード', 'Effect Monster', 'Insect', 'DARK', 3, 1600, 1200, '①：1回合1次，自己主要阶段才能发动。从自己的手卡·墓地选1只「甲虫装机」怪兽当作装备卡使用给这张卡装备。 ②：这张卡在自己场上存在，给这张卡装备的卡被送去自己墓地的场合才能发动。从卡组把1张「甲虫装机」卡加入手卡。 ③：把这张卡当作装备卡使用来装备的怪兽的等级上升3星。'),
(87047074, 'Inzektor Crossbow - Zektarrow', '甲虫装机的魔弓 虫装弓箭', '甲虫装機の魔弓 ゼクトアロー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「甲虫装机」的怪兽才能装备。装备怪兽的攻击力上升500。对方不能对应装备怪兽的效果的发动把魔法·陷阱·效果怪兽的效果发动。'),
(68184115, 'Inzektor Dragonfly', '甲虫装机 豆娘', '甲虫装機 ダンセル', 'Effect Monster', 'Insect', 'DARK', 3, 1000, 1800, '①：1回合1次，自己主要阶段才能发动。从自己的手卡·墓地选1只「甲虫装机」怪兽当作装备卡使用给这张卡装备。 ②：这张卡在自己场上存在，给这张卡装备的卡被送去自己墓地的场合才能发动。从卡组把「甲虫装机 豆娘」以外的1只「甲虫装机」怪兽特殊召唤。 ③：把这张卡当作装备卡使用来装备的怪兽的等级上升3星。'),
(38450736, 'Inzektor Earwig', '甲虫装机 蠼螋', '甲虫装機 ウィーグ', 'Effect Monster', 'Insect', 'DARK', 4, 1000, 1000, '1回合1次，可以从自己的手卡·墓地把1只名字带有「甲虫装机」的怪兽当作装备卡使用给这张卡装备。这张卡当作装备卡使用而装备中的场合，装备怪兽的攻击力·守备力上升这张卡的各自数值。此外，给怪兽装备的这张卡被送去墓地时，装备过的怪兽的攻击力直到结束阶段时上升1000。'),
(44505297, 'Inzektor Exa-Beetle', '甲虫装机 艾可萨兜虫', '甲虫装機 エクサビートル', 'XYZ Monster', 'Insect', 'DARK', 6, 1000, 1000, '6星怪兽×2 这张卡超量召唤成功时，可以选择自己或者对方的墓地1只怪兽当作装备卡使用给这张卡装备。这张卡的攻击力·守备力上升这个效果装备的怪兽的各自一半数值。此外，1回合1次，可以把这张卡1个超量素材取除，选择自己以及对方场上表侧表示存在的卡各1张送去墓地。'),
(26211048, 'Inzektor Exa-Stag', '甲虫装机 艾可萨锹甲', '甲虫装機 エクサスタッグ', 'XYZ Monster', 'Insect', 'DARK', 5, 800, 800, '昆虫族5星怪兽×2 1回合1次，可以把这张卡1个超量素材取除，选择对方的场上·墓地1只怪兽当作装备卡使用给这张卡装备。这张卡的攻击力·守备力上升这个效果装备的怪兽的各自一半数值。'),
(66066482, 'Inzektor Firefly', '甲虫装机 萤火虫', '甲虫装機 リュシオル', 'Effect Monster', 'Insect', 'DARK', 1, 100, 100, '1回合1次，可以从自己的手卡·墓地把1只名字带有「甲虫装机」的怪兽当作装备卡使用给这张卡装备。这张卡被名字带有「甲虫装机」的卡装备的场合，可以把对方场上盖放的卡全部确认。此外，这张卡当作装备卡使用而装备中的场合，装备怪兽的等级上升1星，攻击力·守备力上升这张卡的各自数值。'),
(259314, 'Inzektor Gauntlet', '甲虫装机的手甲', '甲虫装機の手甲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成守备力上升1000的装备卡，给自己场上1只名字带有「甲虫装机」的怪兽装备。装备怪兽不会被对方的卡的效果破坏。'),
(65844845, 'Inzektor Giga-Cricket', '甲虫装机 吉咖蝼蛄', '甲虫装機 ギガグリオル', 'Effect Monster', 'Insect', 'DARK', 5, 2000, 1300, '可以把自己墓地1只昆虫族怪兽从游戏中除外，墓地的这张卡当作装备卡使用给自己场上1只名字带有「甲虫装机」的怪兽装备。「甲虫装机 吉咖蝼蛄」的这个效果1回合只能使用1次。此外，这张卡当作装备卡使用而装备中的场合，装备怪兽的原本攻击力变成2000，装备怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(94573223, 'Inzektor Giga-Mantis', '甲虫装机 吉咖螳螂', '甲虫装機 ギガマンティス', 'Effect Monster', 'Insect', 'DARK', 6, 2400, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：以自己场上1只「甲虫装机」怪兽为对象才能发动。这张卡从手卡当作装备卡使用给那只自己的「甲虫装机」怪兽装备。 ②：把这张卡当作装备卡使用来装备的怪兽的原本攻击力变成2400。 ③：给怪兽装备的这张卡被送去墓地的场合，以「甲虫装机 吉咖螳螂」以外的自己墓地1只「甲虫装机」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(21977828, 'Inzektor Giga-Weevil', '甲虫装机 吉咖象鼻虫', '甲虫装機 ギガウィービル', 'Effect Monster', 'Insect', 'DARK', 6, NULL, 2600, '这张卡可以从手卡当作装备卡使用给自己场上的名字带有「甲虫装机」的怪兽装备。这张卡当作装备卡使用而装备中的场合，装备怪兽的原本守备力变成2600。此外，给怪兽装备的这张卡被送去墓地的场合，可以从自己墓地选择1只名字带有「甲虫装机」的怪兽特殊召唤。「甲虫装机 吉咖象鼻虫」的这个效果1回合只能使用1次。'),
(52601736, 'Inzektor Hopper', '甲虫装机 蝗虫', '甲虫装機 ホッパー', 'Effect Monster', 'Insect', 'DARK', 4, 1700, 1400, '1回合1次，可以从自己的手卡·墓地把1只名字带有「甲虫装机」的怪兽当作装备卡使用给这张卡装备。这张卡当作装备卡使用而装备中的场合，装备怪兽的等级上升4星。此外，可以通过把当作装备卡使用而装备中的这张卡送去墓地，这个回合装备怪兽可以直接攻击对方玩家。这个效果发动的回合，装备怪兽以外的怪兽不能攻击。'),
(69207766, 'Inzektor Hornet', '甲虫装机 大黄蜂', '甲虫装機 ホーネット', 'Effect Monster', 'Insect', 'DARK', 3, 500, 200, '①：1回合1次，自己主要阶段才能发动。从自己的手卡·墓地选1只「甲虫装机」怪兽当作装备卡使用给这张卡装备。 ②：把这张卡当作装备卡使用来装备的怪兽的等级上升3星，攻击力·守备力上升这张卡的各自数值。 ③：把给怪兽装备的这张卡送去墓地，以场上1张卡为对象才能发动。那张卡破坏。'),
(2461031, 'Inzektor Ladybug', '甲虫装机 瓢虫', '甲虫装機 グルフ', 'Effect Monster', 'Insect', 'DARK', 2, 500, 100, '1回合1次，可以从自己的手卡·墓地把1只名字带有「甲虫装机」的怪兽当作装备卡使用给这张卡装备。这张卡当作装备卡使用而装备中的场合，装备怪兽的等级上升2星，攻击力·守备力上升这张卡的各自数值。此外，可以把当作装备卡使用而装备中的这张卡送去墓地，选择自己场上1只怪兽，等级上升最多2星。'),
(38643567, 'Inzektor Orb', '甲虫装机的宝珠', '甲虫装機の宝珠', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成攻击力·守备力上升500的装备卡，给自己场上1只名字带有「甲虫装机」的怪兽装备。自己场上的名字带有「甲虫装机」的怪兽1只成为卡的效果的对象时，可以把变成装备卡的这张卡送去墓地，那个效果无效。'),
(97273514, 'Inzektor Picofalena', '甲虫装机 皮可蛾', '甲虫装機 ピコファレーナ', 'Link Monster', 'Insect', 'DARK', NULL, 1000, NULL, '昆虫族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合，丢弃1张手卡，以这张卡以外的自己场上1只昆虫族怪兽为对象才能发动。从卡组选1只昆虫族怪兽当作攻击力·守备力上升500的装备卡使用给作为对象的怪兽装备。 ②：以自己墓地3只昆虫族怪兽为对象才能发动。那些怪兽回到卡组洗切。那之后，自己从卡组抽1张。'),
(16550875, 'Inzektor Sword - Zektkaliber', '甲虫装机的魔剑 虫装王剑', '甲虫装機の魔剣 ゼクトキャリバー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「甲虫装机」的怪兽才能装备。装备怪兽的攻击力·守备力上升800。场上表侧表示存在的这张卡被送去墓地时，选择自己墓地1只名字带有「甲虫装机」的怪兽加入手卡。'),
(70744296, 'Ipiria', '伊匹利亚', 'イピリア', 'Effect Monster', 'Reptile', 'EARTH', 2, 500, 500, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合发动。自己从卡组抽1张。'),
(9628664, 'Iris, the Earth Mother', '地母神 艾莉丝', '地母神アイリス', 'Effect Monster', 'Fairy', 'LIGHT', 6, 2400, 1200, '连锁积累有3个的场合，从自己卡组抽1张卡。同1组连锁上有复数次同名卡的效果发动的场合，这个效果不能发动。'),
(73431236, 'Iron Blacksmith Kotetsu', '名工 虎铁', '名工 虎鉄', 'Flip Effect Monster', 'Beast-Warrior', 'FIRE', 2, 500, 500, '①：这张卡反转的场合发动。从卡组把1张装备魔法卡加入手卡。'),
(45072394, 'Iron Cage', '铁笼子', '鉄の檻', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，自己场上1只怪兽送去墓地。场地区域有「急流山的金宫」存在的场合，也能作为代替把对方场上的怪兽送去墓地。 ②：自己准备阶段，以这张卡的①的效果送去自己或者对方的墓地的1只怪兽为对象才能发动。这张卡破坏，那只怪兽在自己场上特殊召唤。'),
(64662453, 'Iron Call', '钢铁呼唤', 'アイアンコール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有机械族怪兽存在的场合，以自己墓地1只4星以下的机械族怪兽为对象才能发动。那只机械族怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。'),
(26157485, 'Iron Chain Blaster', '链·射击手', 'C・シューター', 'Effect Monster', 'Warrior', 'EARTH', 2, 1100, NULL, '把自己场上存在的1只名字带有「链」的怪兽送去墓地发动。给与对方基本分800分伤害。这个效果1回合只能使用1次。'),
(53152590, 'Iron Chain Coil', '链·线圈人', 'C・コイル', 'Tuner Monster', 'Machine', 'EARTH', 3, 1100, 1600, '选择自己场上存在的1只名字带有「链」的怪兽发动。那只怪兽的攻击力·守备力上升300。这个效果1回合只能使用1次。'),
(19974580, 'Iron Chain Dragon', '链·锁环龙', 'C・ドラゴン', 'Synchro Monster', 'Dragon', 'EARTH', 6, 2500, 1300, '调整＋调整以外的怪兽1只以上 可以把自己墓地存在的名字带有「链」的怪兽全部从游戏中除外。这个效果每除外1只怪兽，这张卡的攻击力直到这个回合的结束阶段时上升200。每次这张卡给与对方基本分战斗伤害，从对方卡组上面把3张卡送去墓地。'),
(53274132, 'Iron Chain Repairman', '链·修理工', 'C・リペアラー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 1200, '这张卡战斗破坏怪兽送去墓地时，给与对方基本分300分伤害。1回合1次，可以把自己墓地存在的「链·修理工」以外的1只名字带有「链」的4星以下的怪兽特殊召唤。这个效果发动的回合这张卡不能攻击。'),
(80769747, 'Iron Chain Snake', '链·锁缚蛇', 'C・スネーク', 'Effect Monster', 'Reptile', 'EARTH', 3, 800, 1200, '自己的主要阶段时可以当作装备卡使用给对方场上存在的1只表侧表示怪兽装备。这张卡装备的怪兽的攻击力·守备力下降800。装备怪兽被战斗破坏送去墓地时，从装备怪兽的控制者的卡组上面把和那只怪兽的等级相同数量的卡送去墓地。'),
(20457551, 'Iron Core Armor', '钢核收纳', '鋼核収納', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「核成」的怪兽才能装备。和装备怪兽进行战斗的对方怪兽的攻击力只在那次伤害计算时下降装备怪兽的等级×100的数值。装备怪兽在结束阶段时被破坏的场合，可以作为代替把这张卡送去墓地。'),
(63018036, 'Iron Core Immediate Disposal', '紧急钢核处分', '緊急鋼核処分', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己卡组选择1张「核成兽的钢核」送去墓地。'),
(34545235, 'Iron Core Luster', '钢核的光辉', '鋼核の輝き', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '把手卡1张「核成兽的钢核」给对方观看发动。对方的魔法·陷阱卡的发动无效并破坏。'),
(36623431, 'Iron Core of Koa''ki Meiru', '核成之钢核', 'コアキメイルの鋼核', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡在墓地存在的场合，可以作为自己的抽卡阶段时进行通常抽卡的代替，把这张卡加入手卡。此外，自己的抽卡阶段时可以从手卡把1只名字带有「核成」的怪兽送去墓地，自己墓地存在的这张卡加入手卡。'),
(53039326, 'Iron Core Specimen Lab', '钢核合成兽研究所', '鋼核合成獣研究所', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己的结束阶段从手卡给1张「核成兽的钢核」对方观看。或者不给观看让这张卡破坏。每次场上存在的名字带有「核成」的怪兽在结束阶段时被破坏，那些怪兽的原本持有者可以从卡组把1只名字带有「核成」的怪兽加入手卡。'),
(46247282, 'Iron Dragon Tiamaton', '铁骑龙提亚马顿', '鉄騎龍ティアマトン', 'Effect Monster', 'Dragon', 'DARK', 4, 2000, NULL, '这张卡不能通常召唤，用这张卡的①的效果才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：3张以上的卡在相同纵列存在的场合才能发动。这张卡从手卡特殊召唤。这个效果在对方回合也能发动。 ②：这张卡特殊召唤成功的场合发动。和这张卡相同纵列的其他卡全部破坏。 ③：只要这张卡在怪兽区域存在，和这张卡相同纵列的没有使用的区域不能使用。'),
(34559295, 'Iron Draw', '钢铁抽牌', 'アイアンドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的怪兽只有机械族效果怪兽2只的场合才能发动。自己从卡组抽2张。这张卡的发动后，直到回合结束时自己只能有1次把怪兽特殊召唤。'),
(41916534, 'Iron Hans', '铁汉斯', '鉄のハンス', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 800, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合才能发动。从卡组把1只「铁骑士」特殊召唤。这个效果的处理时场地区域没有「急流山的金宫」存在的场合，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。 ②：场地区域有「急流山的金宫」存在的场合，这张卡的攻击力上升自己场上的「铁骑士」数量×1000。'),
(73405179, 'Iron Knight', '铁骑士', '鉄の騎士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1700, 700, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有「铁汉斯」存在的场合，这张卡的攻击力下降1000。 ②：场上的这张卡被效果送去墓地的场合或者被战斗破坏的场合才能发动。从卡组把1只「铁汉斯」加入手卡。场地区域有「急流山的金宫」存在的场合，可以作为代替从卡组把1只战士族怪兽加入手卡。'),
(662857, 'Iron Knight of Revolution', NULL, NULL, 'Link Monster', 'Machine', 'EARTH', NULL, 2400, NULL, NULL),
(12682213, 'Iron Thunder', '铁骑之雷锤', '鉄騎の雷鎚', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：场上的怪兽的效果·魔法·陷阱卡发动时，把基本分支付一半才能发动。那个发动无效并破坏。那之后，和破坏的卡存在过的区域相同纵列的怪兽区域·魔法与陷阱区域有卡存在的场合，那些卡全部破坏。'),
(79185500, 'Ironhammer the Giant', '铁巨人 大铁锤', '鉄巨人アイアンハンマー', 'Effect Monster', 'Rock', 'EARTH', 8, 900, 3500, '自己场上有「异次元超能人·星斗罗宾」「野兽战士 豹人」「凤王兽 铠楼罗」存在的场合，这张卡可以从手卡特殊召唤。这张卡只要在场上表侧表示存在，不能把表示形式变更。此外，1回合1次，选择自己场上1只怪兽才能发动。这个回合，选择的怪兽可以直接攻击对方玩家。'),
(4042268, 'Island Turtle', '岛龟', '島亀', 'Normal Monster', 'Aqua', 'WATER', 4, 1100, 2000, '小岛般大的海龟，从不潜入海中，在其龟壳上栖息着树木与动物。'),
(22657402, 'Isolde, Belle of the Underworld', '冥界丽人 伊索尔德', '冥界の麗人イゾルデ', 'Effect Monster', 'Zombie', 'DARK', 4, 1000, NULL, '这张卡不用这张卡的①的方法不能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：自己场上有「冥界骑士 崔斯坦」存在的场合，这张卡可以从手卡特殊召唤。 ②：以自己场上最多2只不死族怪兽为对象，宣言5～8的任意等级才能发动。那些怪兽直到回合结束时变成宣言的等级。这个效果的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。'),
(59934749, 'Isolde, Two Tales of the Noble Knights', '圣骑士之追想 伊索尔德', '聖騎士の追想 イゾルデ', 'Link Monster', 'Warrior', 'LIGHT', NULL, 1600, NULL, '战士族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1只战士族怪兽加入手卡。这个回合，自己不能把这个效果加入手卡的怪兽以及那些同名怪兽通常召唤·特殊召唤，那些怪兽效果也不能发动。 ②：从卡组把装备魔法卡任意数量送去墓地才能发动（同名卡最多1张）。和送去墓地的卡数量相同等级的1只战士族怪兽从卡组特殊召唤。'),
